  (* [comment removed for export] *)
  Notation HD2 pc mm q pt bits x8 x9 a3 t3 t4 t5 t6 :=
    (CL pc mm q (Z_to_bv 64 (DST + Q3 - 2)) (Z_to_bv 64 (64 - tl)) (Z_to_bv 64 67064) x8 x9 (Z_to_bv 64 64) a3
        (Z_to_bv 64 (SS + O3)) (Z_to_bv 64 (SS + O3 + pt)) (Z_to_bv 64 bits) t3 t4 t5 t6).

  (* [comment removed for export] *)
  Lemma y33_join2 : forall q pt nb bits flag mm (x8 x9 t4 t5 t6 : word),
    X4F' mm SPL BD -> 0 <= q <= Q3 -> 0 <= nb <= pt -> nb <= 8 -> pt - nb + 8 <= L3 -> 0 <= bits <= 64 ->
    (flag = 0 \/ flag = 1) ->
    (forall q' pt' bits' mm' (x8' x9' a3' t3' t4' t5' t6' : word),
       X4F' mm' SPL BD -> q < q' <= Q3 -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= L3) -> 0 <= bits' <= 64 ->
       evt psegs POST (HD2 0x17e20 mm' q' pt' bits' x8' x9' a3' t3' t4' t5' t6')) ->
